export type Language = 'ar' | 'en';
type Params = Record<string, string | number>;
type I18nValue = {
  language: Language;
  locale: string;
  t: (key: TranslationKey, params?: Params) => string;
  number: (value: number) => string;
  dateTime: (value: string | number | Date) => string;
  toggle: () => void;
};

function readLanguage(): Language {
  try { return sessionStorage.getItem('cti_language') === 'en' ? 'en' : 'ar'; } catch { return 'ar'; }
}

const fallback: I18nValue = {
  language: 'ar', locale: 'ar', t: (key, params = {}) => Object.entries(params).reduce<string>((text, [name, replacement]) => text.replaceAll(`{${name}}`, String(replacement)), String(ar[key])),
  number: (value) => new Intl.NumberFormat('ar').format(value),
  dateTime: (value) => new Intl.DateTimeFormat('ar', { dateStyle: 'medium', timeStyle: 'medium', timeZone: 'UTC' }).format(new Date(value)),
  toggle: () => undefined,
};
const Context = createContext<I18nValue>(fallback);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(readLanguage);
  useLayoutEffect(() => {
    document.documentElement.lang = language;
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
    try { sessionStorage.setItem('cti_language', language); } catch { /* session preference is optional */ }
  }, [language]);
  const value = useMemo<I18nValue>(() => {
    const locale = language === 'ar' ? 'ar' : 'en';
    return {
      language, locale,
      t: (key, params = {}) => {
        const template = (language === 'ar' ? ar : en)[key] ?? (import.meta.env.DEV ? `[${key}]` : '');
        return Object.entries(params).reduce((text, [name, replacement]) => text.replaceAll(`{${name}}`, String(replacement)), template);
      },
      number: (value) => new Intl.NumberFormat(locale).format(value),
      dateTime: (value) => new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeStyle: 'medium', timeZone: 'UTC' }).format(new Date(value)),
      toggle: () => setLanguage((current) => current === 'ar' ? 'en' : 'ar'),
    };
  }, [language]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useI18n() {
  return useContext(Context);
}
